default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('PasswordLength', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_laps_password_length)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS [PasswordLength]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_18_9_25_5 }}
    {{ if .Vars.win11cis_domain_joined }}
registry:
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS\PasswordLength:
    title: "18.9.25.5 | Ensure 'Password Settings: Password Length' is set to 'Enabled: 15 or more' | PasswordLength"
    exists: true
    value: {{ .Vars.win11cis_laps_password_length }}
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 18.9.25.5
      NIST800-53R5:
        - IA-5(1)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS')) {
    New-Item -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name 'PasswordLength' -Value $ODV_laps_password_length -PropertyType DWord -Force | Out-Null
exit 0
